import pandas as pd,numpy as np
from scipy.optimize import least_squares
def load(f):
    d=pd.read_csv(f); return d
def simQ(p,d):
    Kq,Tq,Kd,Q0=p[0],p[1],p[2],p[3]
    V=d.voltage_pu.values; Vs=d.voltage_setpoint_pu.values; dt=0.001
    x=0.0; out=np.empty(len(V)); V0=V[0]
    for i in range(len(V)):
        out[i]=Q0+x+Kd*(V[i]-V0)
        x+= dt*(Kq*(Vs[i]-V[i])-x)/Tq
    return out
files=['train/A2_vref_op1.csv','train/A2_vref_op3.csv']
D=[load(f) for f in files]
def res(p):
    return np.concatenate([simQ(p,d)-d.reactive_power_pu.values for d in D])
r=least_squares(res,[1,0.1,0,0.17],bounds=([0,0.001,-50,-1],[50,5,50,1]))
print(r.x, np.std(r.fun))
for d in D:
    e=simQ(r.x,d)-d.reactive_power_pu.values; print(np.std(e), np.abs(e).max())
